import 'dart:io';import 'dart:convert';import 'package:neko_player_pc/catalog.dart';
Future<void> main()async{final api=ProviderClient();final report=<String,dynamic>{};try{final home=await api.catalog();report['catalogCount']=home.cards.length;report['active']=api.enabledProviders.toList();final found=await api.catalog(query:'Dark Machine');final urls=found.cards.where((c)=>ProviderClient.key(c.title).contains('dark machine')).expand((c)=>[c.url,...c.alternatives]).toSet();for(final url in urls){final name=providerForUrl(url);try{final detail=await api.detail(Anime('Dark Machine: The Animation',url,''));final ep=detail.episodes.first;final servers=await api.servers(ep);final data=<String,dynamic>{'url':url,'episode':ep.url,'episodes':detail.episodes.length,'servers':servers.map((s)=>s.name).toList()};for(final s in servers.take(2)){try{final stream=await api.resolve(s,ep);data['resolved_${s.name}']=Uri.parse(stream.url).host;}catch(e){data['error_${s.name}']=e.toString();}}report[name]=data;}catch(e){report[name]={'error':e.toString()};}}}catch(e){report['error']=e.toString();exitCode=1;}finally{api.close();stdout.writeln(const JsonEncoder.withIndent('  ').convert(report));await File('tool/new_sources_probe.json').writeAsString(const JsonEncoder.withIndent('  ').convert(report));}}
